contract.content:
{
  "action": "execute",
  "archetype": "ai-tool",
  "message": "Building an AI-powered institutional knowledge Q&A assistant. Employees ask questions in plain English and get AI-generated answers with citations linking back to source passages from SharePoint, internal wikis, and archived project documents. Admins manage document sources, monitor a dashboard of top questions and coverage gaps (questions without good source answers), review audit logs of who asked what, and export question history to CSV. Leadership receives a periodic email digest summarizing popular topics and unanswered questions. Surfaces lessons learned and prior client deliverables to prevent duplicate work.",
  "flags": ["has-users", "has-admin", "ai-rag", "ai-chat", "sharepoint", "notifications-email", "exports-csv"],
  "tasks": [
    {
      "scope": "database",
      "summary": "Stores users, document sources, ingested documents, questions asked, AI-generated answers, citations, and audit logs.",
      "task": "Tables: users, sources, documents, questions, answers, citations, audit_logs. Indexes: FK columns, questions.created_at DESC, audit_logs.created_at DESC, answers.confidence (for coverage-gap queries). Column-level contract: data_model.",
      "dockerfile": "Dockerfile.postgres",
      "rules": [],
      "snippets": [],
      "primarySnippet": null
    },
    {
      "scope": "vectordb",
      "summary": "Stores embedded chunks of ingested documents for semantic retrieval during Q&A.",
      "task": "pgvector extension. Table: doc_chunks(id SERIAL PK, document_id INTEGER NOT NULL, chunk_index INTEGER, content TEXT, embedding vector(3072), metadata JSONB, created_at TIMESTAMPTZ DEFAULT NOW()). Index: HNSW on embedding (vector_cosine_ops). Embedding model: text-embedding-3-large via MGA /embeddings.",
      "dockerfile": "Dockerfile.pgvector",
      "rules": [],
      "snippets": [],
      "primarySnippet": "vectordb/vectordb-connections.ts"
    },
    {
      "scope": "backend",
      "summary": "Handles Q&A requests with RAG retrieval+citations, document source registration and ingestion, admin dashboard data, audit logs, CSV export, and the leadership email digest job.",
      "task": "Data: pg Pool from env (DATABASE_* and VECTORDB_* hosts). Endpoints + bodies: api_contract. Behaviors + rules + side-effects: business_logic_contract. RAG flow: embed question via MGA text-embedding-3-large, top-K cosine search on doc_chunks, call MGA claude-opus-4.7 assistant with retrieved passages, return answer + citations[]; flag low-confidence as coverage gap. Ingestion: SharePoint connector + manual upload for wikis/archived project docs; chunk → embed → upsert. Weekly digest cron summarizes top questions + unanswered (low-confidence) topics, emails leadership. Auth: x-amzn-oidc-data JWT sub/email; first login creates users row; role defaults 'employee', admins set manually.",
      "dockerfile": "Dockerfile.node",
      "rules": [],
      "snippets": [],
      "primarySnippet": "backend/express-server-template.ts"
    },
    {
      "scope": "frontend",
      "summary": "Chat-style Q&A interface for employees with clickable citations, plus an admin dashboard for sources, coverage gaps, audit logs, and CSV export.",
      "task": "Views + components: ui_contract. Endpoints + body shapes: api_contract (prepend /api/). Citation chips open a source passage modal. Admin dashboard surfaces coverage gaps as first-class view. States: spinner, empty CTA, toast on 4xx/5xx, 404 page, disabled submit during POST, streaming/loading indicator while answer generates. Responsive. Preserve terminology: 'institutional knowledge', 'lessons learned', 'initiatives', 'client deliverables'.",
      "dockerfile": "Dockerfile.react",
      "rules": [],
      "snippets": [],
      "primarySnippet": "frontend/AppScaffold.tsx"
    },
    {
      "scope": "integration",
      "summary": "Wires database, vectordb, backend, and frontend together for local development.",
      "task": "Wire database, vectordb, backend, frontend. Backend env: DATABASE_HOST=database, DATABASE_PORT=5432, DATABASE_NAME=knowledge_qa, DATABASE_USER=knowledge_qa_user, DATABASE_PASSWORD=localdev123, VECTORDB_HOST=vectordb, VECTORDB_PORT=5433, VECTORDB_NAME=knowledge_qa_vec, VECTORDB_USER=knowledge_qa_vec_user, VECTORDB_PASSWORD=localdev123, MGA_API_KEY, SHAREPOINT_*, SMTP_* for digest. nginx.local.conf proxy /api→backend:3000. depends_on chain: database+vectordb → backend → frontend. Healthchecks on every service. Named volumes per DB.",
      "dockerfile": null,
      "rules": [],
      "snippets": [],
      "primarySnippet": "integration/docker-compose-fullstack.yml"
    }
  ],
  "data_model": {
    "tables": [
      {
        "name": "users",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "oidc_sub", "type": "TEXT UNIQUE NOT NULL"},
          {"name": "email", "type": "VARCHAR(255) NOT NULL"},
          {"name": "role", "type": "VARCHAR(32) NOT NULL DEFAULT 'employee'"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "sources",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "name", "type": "VARCHAR(255) NOT NULL"},
          {"name": "kind", "type": "VARCHAR(32) NOT NULL"},
          {"name": "config", "type": "JSONB NOT NULL DEFAULT '{}'::jsonb"},
          {"name": "last_ingested_at", "type": "TIMESTAMPTZ"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "documents",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "source_id", "type": "INTEGER REFERENCES sources(id) ON DELETE CASCADE"},
          {"name": "title", "type": "TEXT NOT NULL"},
          {"name": "url", "type": "TEXT"},
          {"name": "content", "type": "TEXT"},
          {"name": "metadata", "type": "JSONB NOT NULL DEFAULT '{}'::jsonb"},
          {"name": "ingested_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "questions",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "user_id", "type": "INTEGER NOT NULL REFERENCES users(id)"},
          {"name": "text", "type": "TEXT NOT NULL"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "answers",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "question_id", "type": "INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE"},
          {"name": "text", "type": "TEXT NOT NULL"},
          {"name": "confidence", "type": "REAL"},
          {"name": "is_coverage_gap", "type": "BOOLEAN NOT NULL DEFAULT FALSE"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "citations",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "answer_id", "type": "INTEGER NOT NULL REFERENCES answers(id) ON DELETE CASCADE"},
          {"name": "document_id", "type": "INTEGER REFERENCES documents(id)"},
          {"name": "passage", "type": "TEXT NOT NULL"},
          {"name": "score", "type": "REAL"}
        ]
      },
      {
        "name": "audit_logs",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "user_id", "type": "INTEGER REFERENCES users(id)"},
          {"name": "action", "type": "VARCHAR(64) NOT NULL"},
          {"name": "detail", "type": "JSONB NOT NULL DEFAULT '{}'::jsonb"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      }
    ]
  },
  "api_contract": {
    "version": 1,
    "endpoints": [
      {"method": "GET", "path": "/whoami", "response": {"status": 200, "body": "{ id, email, role }"}},
      {"method": "POST", "path": "/questions", "request": {"text": "string required"}, "response": {"status": 201, "body": "{ question: {id, text, created_at}, answer: {id, text, confidence, is_coverage_gap}, citations: [{id, document_id, document_title, document_url, passage, score}] }"}},
      {"method": "GET", "path": "/questions", "response": {"status": 200, "body": "{ items: [{id, text, created_at, answer_preview}], total }"}},
      {"method": "GET", "path": "/questions/:id", "response": {"status": 200, "body": "{ question, answer, citations[] }"}},
      {"method": "GET", "path": "/documents/:id", "response": {"status": 200, "body": "{ id, title, url, content, metadata, source: {id, name, kind} }"}},
      {"method": "GET", "path": "/admin/sources", "response": {"status": 200, "body": "{ items: [{id, name, kind, last_ingested_at, doc_count}] }"}},
      {"method": "POST", "path": "/admin/sources", "request": {"name": "string required", "kind": "string required (sharepoint|wiki|archive|upload)", "config": "object"}, "response": {"status": 201, "body": "{ id, name, kind }"}},
      {"method": "POST", "path": "/admin/sources/:id/ingest", "response": {"status": 202, "body": "{ status, queued_at }"}},
      {"method": "POST", "path": "/admin/documents/upload", "request": {"source_id": "int required", "title": "string", "content": "string required"}, "response": {"status": 201, "body": "{ id, title }"}},
      {"method": "GET", "path": "/admin/dashboard", "response": {"status": 200, "body": "{ top_questions: [...], usage_trend: [...], coverage_gaps: [{question_id, text, confidence, asked_count}] }"}},
      {"method": "GET", "path": "/admin/audit-logs", "response": {"status": 200, "body": "{ items: [{id, user_email, action, detail, created_at}], total }"}},
      {"method": "GET", "path": "/admin/questions/export.csv", "response": {"status": 200, "body": "text/csv stream"}}
    ]
  },
  "ui_contract": {
    "primary_view": "Ask a question about institutional knowledge",
    "primary_action": "submit a natural-language question and read the AI answer with citations",
    "secondary_views": ["Question history", "Source passage viewer", "Admin dashboard with coverage gaps", "Admin source library", "Admin audit log", "Admin CSV export"],
    "components": [
      {"name": "AskBar", "role": "primary natural-language question input"},
      {"name": "AnswerCard", "role": "AI-generated answer with confidence indicator"},
      {"name": "CitationChip", "role": "clickable citation linking to source passage"},
      {"name": "SourcePassageModal", "role": "view the cited passage in context of its source document"},
      {"name": "QuestionHistoryList", "role": "employee's past questions and answers"},
      {"name": "AdminDashboard", "role": "top questions, usage trends, and coverage gaps"},
      {"name": "CoverageGapsPanel", "role": "first-class view of questions with low-confidence or missing answers"},
      {"name": "SourceLibrary", "role": "admin manages SharePoint, wiki, and archived project document sources"},
      {"name": "DocumentUploadForm", "role": "manual upload for wikis and archived project deliverables"},
      {"name": "AuditLogTable", "role": "who asked what and which sources were cited"},
      {"name": "ExportCsvButton", "role": "download question history as CSV"}
    ]
  },
  "business_logic_contract": {
    "triggers": [
      {"event": "user_first_login", "action": "create users row from OIDC sub/email; default role='employee'"},
      {"event": "question_submitted", "action": "embed question, retrieve top-K chunks from vectordb, call MGA claude-opus-4.7 assistant with passages, persist question+answer+citations, flag is_coverage_gap=true when confidence below threshold or no citations"},
      {"event": "source_ingest_triggered", "action": "pull documents from SharePoint connector or accept uploaded wiki/archive docs, chunk text, embed via MGA text-embedding-3-large, upsert into doc_chunks, update sources.last_ingested_at"},
      {"event": "weekly_digest_cron", "action": "aggregate top questions + coverage gaps for prior period, email summary to leadership recipients"}
    ],
    "rules": [
      "employees can only see their own questions and answers",
      "/admin/* endpoints require role='admin'",
      "only admins can create sources, trigger ingestion, upload documents, view dashboard/audit logs, or export CSV",
      "every question must record user_id for audit traceability",
      "answers with confidence below threshold or zero citations are marked is_coverage_gap=true and surfaced in admin dashboard"
    ],
    "side_effects": [
      "audit log on every write (question asked, source created, ingest triggered, document uploaded, CSV exported)",
      "audit log on citation generation capturing which documents were cited per answer",
      "weekly email digest to leadership"
    ]
  },
  "vector_engine": "pgvector",
  "mga_assistants": [
    {
      "key": "default",
      "name": "Institutional Knowledge Assistant",
      "description": "Answers employee questions about institutional knowledge, lessons learned, initiatives, and client deliverables using indexed SharePoint, wiki, and archived project documents. Always cites source passages.",
      "model": "claude-opus-4.7",
      "tool_keys": [],
      "starter_messages": [
        "What lessons learned do we have from past initiatives in this domain?",
        "Has a client deliverable like this been produced before?",
        "Summarize what we know about our onboarding process."
      ],
      "instructions": "Answer using only the retrieved passages. Always include citations. If retrieved context is insufficient, say so clearly so the question can be flagged as a coverage gap."
    }
  ]
}
